#[test]
fn sqlite_snapshot_semio_presentation_all_shapes_placeholders_typed_blocks_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioPresentationSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioPresentationSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioPresentationSnapshot as store::ArtifactDsl>::print_dsl(&s));assert_eq!(restore(&project(&SemioPresentationSnapshot::default())).unwrap(),SemioPresentationSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_presentation_rejects_owner_fk_placeholder_and_block_aliases(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_presentation_layout").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_presentation_slide").unwrap().rows[0].values[4]=SqliteValue::Integer(999),2=>db.table_mut("semio_presentation_shape").unwrap().rows[0].values[3]=SqliteValue::Integer(1),3=>db.table_mut("semio_presentation_placeholder").unwrap().rows[0].values[2]=SqliteValue::Text("unexpected".into()),_=>{let id=db.table("semio_presentation_slide").unwrap().rows[0].integer(5).unwrap();db.table_mut("semio_presentation_slide").unwrap().rows[1].values[5]=SqliteValue::Integer(id);}}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioPresentationSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_presentation_independent_layout_master_join_and_picture_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT semio_presentation_layout.native_id AS layout,semio_presentation_master.native_id AS master FROM semio_presentation_layout JOIN semio_presentation_master ON master_id=semio_presentation_master.id').get();if(r.layout!=='layout'||r.master!=='master')throw Error('layout FK');if(db.query('SELECT length(bytes) AS n FROM semio_presentation_picture').get().n!==3)throw Error('picture bytes');db.query(\"UPDATE semio_presentation_picture SET mime='independently edited'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let SlideShape::Picture{image,..}=&mut expected.slides[0].shapes[8]{image.mime="independently edited".into();}assert_eq!(r,expected);}

